// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 640, H = 470;
draw.viewbox(0, 0, W, H);

/* ── Nonlinear world→screen maps (piecewise; ln for p) ── */
var XA = [[-60, 64], [0, 172], [0.01, 186], [100, 410], [374, 534], [400, 556]];
var YA = [[0, 392], [0.0005, 372], [0.001, 356], [0.006, 326], [1, 236], [218, 68], [230, 56]];
function lerpArr(A, v, logY) {
  if (v <= A[0][0]) return A[0][1];
  if (v >= A[A.length - 1][0]) return A[A.length - 1][1];
  for (var i = 0; i < A.length - 1; i++) {
    if (v >= A[i][0] && v <= A[i + 1][0]) {
      var a = A[i], b = A[i + 1], t;
      if (logY && a[0] > 0 && b[0] > 0 && v > 0) {
        t = (Math.log(v) - Math.log(a[0])) / (Math.log(b[0]) - Math.log(a[0]));
      } else t = (v - a[0]) / (b[0] - a[0]);
      return a[1] + t * (b[1] - a[1]);
    }
  }
  return A[A.length - 1][1];
}
function sx(T) { return lerpArr(XA, T, false); }
function sy(p) { return lerpArr(YA, Math.max(p, 0), true); }
function pts(arr) { return arr.map(function (q) { return sx(q[0]) + ',' + sy(q[1]); }).join(' '); }

/* ── Coexistence data (world control points) ── */
var FUS = [[0.006, 0.01], [0.5, -1], [2, -3], [10, -8], [50, -15], [150, -22], [235, -27]]; // (p,T)
var VAP = [[0.01, 0.006], [5, 0.009], [15, 0.017], [30, 0.042], [50, 0.12], [70, 0.31], [100, 1], [130, 2.7], [160, 6.2], [200, 15.5], [240, 33], [280, 64], [320, 120], [350, 168], [374, 218]]; // (T,p)
var SUB = [[-52, 0.0009], [-40, 0.0013], [-30, 0.002], [-20, 0.003], [-10, 0.0045], [0.01, 0.006]]; // (T,p)

function interpLogY(ptsXY, x) { // ptsXY: [x, y], y>0 interpolated in ln y
  if (x <= ptsXY[0][0]) return ptsXY[0][1];
  if (x >= ptsXY[ptsXY.length - 1][0]) return ptsXY[ptsXY.length - 1][1];
  for (var i = 0; i < ptsXY.length - 1; i++) {
    var a = ptsXY[i], b = ptsXY[i + 1];
    if (x >= a[0] && x <= b[0]) {
      var t = (x - a[0]) / (b[0] - a[0]);
